CREATE TABLE `espectadores` (`id_espectador` INT NOT NULL AUTO_INCREMENT, `nombre` VARCHAR(110) NOT NULL COMMENT 'Nombre completo', `correo` VARCHAR(160) NOT NULL, `ciudad` VARCHAR(90), `fecha_registro` DATE NOT NULL, `activo` TINYINT(1) NOT NULL DEFAULT 1, PRIMARY KEY (`id_espectador`)) ENGINE=InnoDB COMMENT='Personas registradas';
CREATE TABLE `generos_cine` (`id_genero_cine` INT NOT NULL AUTO_INCREMENT, `nombre` VARCHAR(100) NOT NULL, `descripcion` VARCHAR(180), PRIMARY KEY (`id_genero_cine`)) ENGINE=InnoDB COMMENT='Clasificación de recursos';
CREATE TABLE `peliculas` (`id_pelicula` INT NOT NULL AUTO_INCREMENT, `id_genero_cine` INT NOT NULL, `nombre` VARCHAR(130) NOT NULL, `precio_entrada` DECIMAL(11,2) NOT NULL, `funciones` INT NOT NULL DEFAULT 0, `activo` TINYINT(1) NOT NULL DEFAULT 1, PRIMARY KEY (`id_pelicula`), KEY `idx_recurso_categoria` (`id_genero_cine`), CONSTRAINT `fk_recurso_categoria` FOREIGN KEY (`id_genero_cine`) REFERENCES `generos_cine` (`id_genero_cine`)) ENGINE=InnoDB COMMENT='Recursos o artículos del catálogo';
CREATE TABLE `complejos` (`id_complejo` INT NOT NULL AUTO_INCREMENT, `nombre` VARCHAR(110) NOT NULL, `ciudad` VARCHAR(90) NOT NULL, `fecha_apertura` DATE, PRIMARY KEY (`id_complejo`)) ENGINE=InnoDB COMMENT='Ubicaciones operativas';
CREATE TABLE `taquilleros` (`id_taquillero` INT NOT NULL AUTO_INCREMENT, `id_complejo` INT NOT NULL, `nombre` VARCHAR(110) NOT NULL, `salario` DECIMAL(11,2), `fecha_ingreso` DATE, `activo` TINYINT(1) NOT NULL DEFAULT 1, PRIMARY KEY (`id_taquillero`), KEY `idx_empleado_sede` (`id_complejo`), CONSTRAINT `fk_empleado_sede` FOREIGN KEY (`id_complejo`) REFERENCES `complejos` (`id_complejo`)) ENGINE=InnoDB COMMENT='Personal';
CREATE TABLE `compras` (`id_compra` INT NOT NULL AUTO_INCREMENT, `id_espectador` INT NOT NULL, `id_taquillero` INT NOT NULL, `id_complejo` INT NOT NULL, `fecha` DATE NOT NULL, `estado` VARCHAR(25) NOT NULL, `total` DECIMAL(12,2) NOT NULL, `comentario` VARCHAR(180), PRIMARY KEY (`id_compra`), KEY `idx_operacion_persona` (`id_espectador`), KEY `idx_operacion_empleado` (`id_taquillero`), KEY `idx_operacion_sede` (`id_complejo`), CONSTRAINT `fk_operacion_persona` FOREIGN KEY (`id_espectador`) REFERENCES `espectadores` (`id_espectador`), CONSTRAINT `fk_operacion_empleado` FOREIGN KEY (`id_taquillero`) REFERENCES `taquilleros` (`id_taquillero`), CONSTRAINT `fk_operacion_sede` FOREIGN KEY (`id_complejo`) REFERENCES `complejos` (`id_complejo`)) ENGINE=InnoDB COMMENT='Registro principal de operaciones';
CREATE TABLE `entradas_compradas` (`id_entrada_comprada` INT NOT NULL AUTO_INCREMENT, `id_compra` INT NOT NULL, `id_pelicula` INT NOT NULL, `cantidad` INT NOT NULL, `precio_unitario` DECIMAL(11,2) NOT NULL, `descuento` DECIMAL(10,2) NOT NULL DEFAULT 0, PRIMARY KEY (`id_entrada_comprada`), KEY `idx_detalle_operacion` (`id_compra`), KEY `idx_detalle_recurso` (`id_pelicula`), CONSTRAINT `fk_detalle_operacion` FOREIGN KEY (`id_compra`) REFERENCES `compras` (`id_compra`), CONSTRAINT `fk_detalle_recurso` FOREIGN KEY (`id_pelicula`) REFERENCES `peliculas` (`id_pelicula`)) ENGINE=InnoDB COMMENT='Detalle de recursos por operación';
CREATE TABLE `pagos_compra` (`id_pago_compra` INT NOT NULL AUTO_INCREMENT, `id_compra` INT NOT NULL, `fecha_pago` DATE NOT NULL, `monto` DECIMAL(12,2) NOT NULL, `metodo` VARCHAR(25) NOT NULL, `confirmado` TINYINT(1) NOT NULL DEFAULT 1, PRIMARY KEY (`id_pago_compra`), KEY `idx_pago_operacion` (`id_compra`), CONSTRAINT `fk_pago_operacion` FOREIGN KEY (`id_compra`) REFERENCES `compras` (`id_compra`)) ENGINE=InnoDB COMMENT='Movimientos de cobro';
CREATE TABLE `valoraciones` (`id_valoracion` INT NOT NULL AUTO_INCREMENT, `id_compra` INT NOT NULL, `fecha_evento` DATE NOT NULL, `tipo` VARCHAR(50) NOT NULL, `descripcion` VARCHAR(220), `puntuacion` INT, PRIMARY KEY (`id_valoracion`), KEY `idx_evento_operacion` (`id_compra`), CONSTRAINT `fk_evento_operacion` FOREIGN KEY (`id_compra`) REFERENCES `compras` (`id_compra`)) ENGINE=InnoDB COMMENT='Eventos de seguimiento asociados a una operación';
